import { ShadowConfig, TiledBoolProp } from "type";
import { GameScene } from "../GameScene";
import { calculateAngle, formatProperties } from "utils";

export class Shadow {
  constructor(scene: GameScene, config: ShadowConfig) {
    this.config = config;
    this.scene = scene;
    const props = formatProperties<"rectangle" | "static">(config.properties);

    const rectangle = props.rectangle as TiledBoolProp;
    const staticProp = props.static as TiledBoolProp;

    const sunShadow = this.createShadow();

    this.sprites = {
      sun: sunShadow,
      lights: [],
    };
  }
  private scene: GameScene;
  private config: ShadowConfig;

  private sprites: {
    sun: Phaser.GameObjects.Sprite;
    lights: Phaser.GameObjects.Sprite[];
  };

  private createShadow = () => {
    const { height, width, x, y, id } = this.config;

    const sprite = this.scene.add.sprite(
      x,
      y+height,
      "shadow_texture",
    );
    sprite.setScale(width / sprite.width, height / sprite.height);
    sprite.setDepth(Infinity);
    sprite.setOrigin(0, 0);
    sprite.setAlpha(0.5)

    sprite.setAngle(90+90 + 45)

    return sprite;
  };

  private rotateSunShadow = () => {
    const { sun: sunSprite } = this.sprites;
    const { x = 0, y = 0 } = this.scene.sun?.sunPosition || {};
    const { x: sX, y: sY } = sunSprite;
    const angle = calculateAngle(x, y, sX, sY);
    sunSprite.setAngle(angle);
  };

  update = () => {
    // this.rotateSunShadow();
  };
}
